record.field:
task_templates = [
    {
        'ten_cv': 'Phân tích yêu cầu',
        'mo_ta': 'Thu thập và phân tích yêu cầu khách hàng',
        'ngay_bd': datetime.date.today(),
        'ngay_kt': datetime.date.today() + datetime.timedelta(days=7),
    },
    {
        'ten_cv': 'Thiết kế hệ thống',
        'mo_ta': 'Thiết kế kiến trúc và cơ sở dữ liệu',
        'ngay_bd': datetime.date.today(),
        'ngay_kt': datetime.date.today() + datetime.timedelta(days=14),
    },
    {
        'ten_cv': 'Tạo base theo thiết kế',
        'mo_ta': 'Triển khai code theo thiết kế',
        'ngay_bd': datetime.date.today() + datetime.timedelta(days=5),
        'ngay_kt': datetime.date.today() + datetime.timedelta(days=30),
    },
]

for project in records:
    for tmpl in task_templates:
        count = len(env['cong_viec'].search([('du_an_id', '=', project.id)]))
        ma_cv = f"{project.ma_du_an}CV{count + 1:03d}"

        env['cong_viec'].create({
            'ma_cv': ma_cv,
            'ten_cv': tmpl['ten_cv'],
            'mo_ta': tmpl['mo_ta'],
            'ngay_bd': tmpl.get('ngay_bd'),
            'ngay_kt': tmpl.get('ngay_kt'),
            'du_an_id': project.id,
            'trang_thai': 'moi',
            'nhan_vien_phu_trach_ids': [(4, project.phu_trach_id.id)] if project.phu_trach_id else [],
        })
